const $=id=>document.getElementById(id);
let stages=[],index=0,route=null,affection=0,answered=false,audioOn=false,audioContext=null,oscillator=null,gain=null;
function begin(){route=null;affection=0;stages=intro.slice();index=0;$('startOverlay').classList.add('hidden');$('endOverlay').classList.add('hidden');$('chapterLabel').textContent='A little visual novel';render()}
function render(){const stage=stages[index];if(!stage)return;if(stage.ending){showEnding();return}answered=false;$('sceneLabel').textContent=stage.scene;$('chapterPill').textContent=stage.pill;$('speaker').textContent=stage.speaker;$('dialogueText').textContent=stage.text;$('choices').innerHTML='';$('choices').classList.toggle('show',!!stage.options);$('nextBtn').style.display=stage.options?'none':'flex';$('chapterLabel').textContent=route?`A story with ${characters[route].name}`:'A little visual novel';$('progressFill').style.width=`${Math.round(index/(stages.length-1)*100)}%`;const el=$('character');if(stage.char){el.innerHTML=characters[stage.char].image;el.className=`character ${characters[stage.char].side}`}else{el.className='character hidden'}if(stage.options)stage.options.forEach((option,n)=>{const button=document.createElement('button');button.className='choice';button.innerHTML=`<span>${option.hint}</span>${option.label}`;button.addEventListener('click',()=>choose(option));$('choices').appendChild(button)})}
function choose(option){if(answered)return;answered=true;if(option.route){route=option.route;affection=1;stages=[...intro,...routeStories[route]]}else affection+=option.points||0;$('speaker').textContent=characters[route].name;$('dialogueText').textContent=option.reply;$('choices').classList.remove('show');$('nextBtn').style.display='flex';$('nextBtn').focus()}
function next(){const stage=stages[index];if(stage?.options&&!answered)return;index++;render()}
function showEnding(){const akari=route==='akari',good=affection>=4;$('progressFill').style.width='100%';$('chapterLabel').textContent='The end';$('endingIcon').textContent=good?'✿':'☾';$('endingEyebrow').textContent=good?'A special ending':`A ${akari?'riverside':'greenhouse'} ending`;$('endingTitle').textContent=good?(akari?'Pages in the golden light':'Where the moonflowers bloom'):(akari?'A sketch for tomorrow':'A garden, slowly growing');$('endingText').textContent=good?(akari?'You and Akari make a little ritual of the riverside: shared stories, unfinished sketches, and the comfort of being understood. Some beginnings are quiet—and all the more beautiful for it.':'You and Hana keep returning to the greenhouse, watching the moonflowers open one by one. Beside her, you learn that trust, like a garden, grows at its own unhurried pace.'):(akari?'You and Akari part with a new promise to meet again. Her sketchbook is full of possibilities, and so is the blank page between you.':'You and Hana leave the greenhouse with muddy hands and an invitation to come back. The seedlings are small, but the garden has all summer to grow.');$('endOverlay').classList.remove('hidden')}
$('startBtn').addEventListener('click',begin);$('nextBtn').addEventListener('click',next);$('restartBtn').addEventListener('click',()=>{if(!$('startOverlay').classList.contains('hidden'))return;begin()});$('playAgain').addEventListener('click',begin);$('otherRoute').addEventListener('click',begin);document.addEventListener('keydown',e=>{if(e.key===' '||e.key==='Enter'){if(!$('startOverlay').classList.contains('hidden')){begin();e.preventDefault()}else if(!$('endOverlay').classList.contains('hidden')){begin();e.preventDefault()}else if($('nextBtn').style.display!=='none'){next();e.preventDefault()}}});
$('soundBtn').addEventListener('click',async()=>{audioOn=!audioOn;$('soundBtn').innerHTML=`♫ <span class="sound-label">SOUND ${audioOn?'ON':'OFF'}</span>`;if(audioOn){try{audioContext=audioContext||new(window.AudioContext||window.webkitAudioContext)();await audioContext.resume();if(!oscillator){oscillator=audioContext.createOscillator();gain=audioContext.createGain();oscillator.type='sine';oscillator.frequency.value=261.63;gain.gain.value=.012;oscillator.connect(gain);gain.connect(audioContext.destination);oscillator.start()}gain.gain.setTargetAtTime(.012,audioContext.currentTime,.4)}catch(error){audioOn=false;$('soundBtn').innerHTML='♫ <span class="sound-label">SOUND OFF</span>'}}else if(gain&&audioContext)gain.gain.setTargetAtTime(0,audioContext.currentTime,.2)});
</script>
